import{_ as a,o as n,a as p,b as c}from"./app.DKoEZOcr.js";const t="/ascendc.github.io/pr/5487/assets/atomic_operation_gm_global_count.Cy_cbWdu.png",l="/ascendc.github.io/pr/5487/assets/atomic_operation_ub_block_local_count.Ca6FL5sP.png",i="/ascendc.github.io/pr/5487/assets/atomic_operation_address_layout.CRqpMTnr.png",u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMT算子性能优化","link":"/guide/operator_practice/simt_operator_optimization/simt_operator_optimization"},{"text":"指令优化","link":"/guide/operator_practice/simt_operator_optimization/instruction_optimization/atomic_instruction_optimization"},{"text":"原子操作指令优化","link":"/guide/operator_practice/simt_operator_optimization/instruction_optimization/atomic_instruction_optimization"}]},"headers":[],"relativePath":"guide/operator_practice/simt_operator_optimization/instruction_optimization/atomic_instruction_optimization.md","filePath":"guide/operator_practice/simt_operator_optimization/instruction_optimization/atomic_instruction_optimization.md","outlineHeaders":[{"level":2,"title":"通过分层归约将原子操作从GM迁移至UB","slug":"通过分层归约将原子操作从GM迁移至UB","link":"#通过分层归约将原子操作从GM迁移至UB"},{"level":2,"title":"非必要不使用原子操作的返回值","slug":"非必要不使用原子操作的返回值","link":"#非必要不使用原子操作的返回值"},{"level":2,"title":"分散GM上原子操作的目标地址","slug":"分散GM上原子操作的目标地址","link":"#分散GM上原子操作的目标地址"}],"lastUpdated":1787050286000}'),e={name:"guide/operator_practice/simt_operator_optimization/instruction_optimization/atomic_instruction_optimization.md"};function o(r,s,d,_,h,g){return n(),p("div",null,[...s[0]||(s[0]=[c('<div><article class="markdown-body"><h1>原子操作指令优化</h1><p>【优先级】高</p><p>【描述】SIMT编程模式下，多个线程更新同一个内存地址时需要使用<a href="../../../../api/SIMT-API/atomic_operations/atomic_operations_intro.html">原子操作接口</a>保证更新结果正确。原子操作属于高开销指令，其耗时由两方面决定：一是同一地址上的原子操作只能排队依次执行，二是单条原子指令的处理开销。</p><p>原子操作需要完整完成“读出旧值—计算新值—写回新值”三个步骤。若多个线程同时更新同一地址且缺乏保护，可能出现多个线程读取到相同旧值、后写回的结果覆盖先写回的结果，导致部分更新丢失。原子操作为避免此类丢失，保证三个步骤作为一个不可分割的整体完成，因此同一地址上的多个原子操作无法并行执行，只能排队依次执行。同一地址上排队的原子操作越多，总耗时越高。</p><p>因此原子操作的优化围绕“减少同一地址上排队的原子操作次数”与“降低单条原子指令的处理开销”两点展开，具体可从以下方面进行优化：</p><ul><li><strong>通过分层归约将原子操作从GM迁移至Unified Buffer（UB）</strong>：Global Memory（GM）位于AI Core外部，访问路径较长、延迟较高；UB位于AI Core内部，访问路径较短、延迟较低。且UB为线程块私有，不同线程块的UB原子操作互不竞争。先在各线程块的UB中局部归约、再向GM汇总，可同时降低单次处理开销并减少同一地址上排队的原子操作次数。</li><li><strong>非必要不使用原子操作的返回值</strong>：是否使用返回值会影响编译器生成的原子指令，不使用返回值时编译器可生成处理开销更低的优化指令。</li><li><strong>分散GM上原子操作的目标地址</strong>：当原子操作因业务需要必须在GM上执行时，由于GM原子操作以128B Sector（扇区）为处理粒度，目标地址集中在同一个Sector内时处理效率较低，应通过padding等方式使原子目标覆盖更多Sector。该方法仅适用于GM，UB上的原子操作不适用。</li></ul><p>【样例介绍】本节以两个样例为载体说明上述优化方向：</p><ul><li><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/03_simt_api/02_features/01_api_features/02_atomic_operation/atomic_add_perf/README.md">asc_atomic_add接口性能对比样例</a>：包含16个场景、归为5组对照实验，量化内存层级、原子累加组织方式、是否使用返回值、同一地址上的竞争程度与目标地址的Sector分布对原子加性能的影响。每组对照仅改变一个属性，其余配置保持一致。</li><li><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/03_simt_api/03_best_practices/03_instruction_optimizations/atomic_histogram/README.md">Histogram原子操作性能调优样例</a>：对形状为[262144]的uint8_t字节流做直方图统计，输出256个桶的uint32_t计数结果。样例启动64个线程块、每个线程块2048个线程，通过对比“全部线程直接更新GM直方图”与“先在各线程块UB上统计再汇总至GM”两种实现，说明分层归约的优化效果。</li></ul><div data-filter="950"><p>下文性能数据均使用msOpProf工具在Ascend 950PR产品上采集，指标为Task Duration（Task整体耗时，即算子端到端耗时）。</p></div><h2 id="通过分层归约将原子操作从GM迁移至UB">通过分层归约将原子操作从GM迁移至UB<a class="header-anchor" href="#通过分层归约将原子操作从GM迁移至UB">​</a></h2><p>【反例】全部线程直接对GM上的全局直方图执行原子累加。</p><p><strong>图 1</strong> GM全局计数示意图</p><p><img src="'+t+`" alt></p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="nf">__launch_bounds__</span><span class="p">(</span><span class="n">THREADS_PER_BLOCK</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">histogram_gm_global</span><span class="p">(</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="o">*</span><span class="w"> </span><span class="n">histogram</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">byte_count</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">gridDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(;</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">byte_count</span><span class="p">;</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">+=</span><span class="w"> </span><span class="n">stride</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">asc_atomic_add</span><span class="p">(</span><span class="o">&amp;</span><span class="n">histogram</span><span class="p">[</span><span class="n">input</span><span class="p">[</span><span class="n">index</span><span class="p">]],</span><span class="w"> </span><span class="mi">1U</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>上述实现中，各线程按grid-stride方式遍历输入字节（即每个线程以总线程数为固定步长，分次处理输入中不同位置的字节），直接对GM直方图的对应桶执行原子加1。262144次原子更新全部集中在256个GM地址上，平均每个地址需排队处理1024次原子加，且每次原子加均作用于访问延迟较高的GM。该实现的性能数据如下：</p><table><thead><tr><th align="center">计数位置</th><th align="center">Task Duration（μs）</th></tr></thead><tbody><tr><td align="center">GM</td><td align="center">424.22</td></tr></tbody></table><p>【正例】每个线程块先在UB上维护私有直方图，最后汇总至GM。</p><p><strong>图 2</strong> UB分块计数示意图</p><p><img src="`+l+`" alt></p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="nf">__launch_bounds__</span><span class="p">(</span><span class="n">THREADS_PER_BLOCK</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">histogram_ub_block_local</span><span class="p">(</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="o">*</span><span class="w"> </span><span class="n">histogram</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">byte_count</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">block_histogram</span><span class="p">[</span><span class="n">HISTOGRAM_BIN_COUNT</span><span class="p">];</span><span class="w"> </span><span class="c1">// __ubuf__表示该数组位于UB片上存储。</span>

<span class="w">    </span><span class="c1">// 线程块内线程协作清零UB直方图。</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">bin_index</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span><span class="w"> </span><span class="n">bin_index</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">HISTOGRAM_BIN_COUNT</span><span class="p">;</span><span class="w"> </span><span class="n">bin_index</span><span class="w"> </span><span class="o">+=</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">block_histogram</span><span class="p">[</span><span class="n">bin_index</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>
<span class="w">    </span><span class="n">asc_syncthreads</span><span class="p">();</span>

<span class="w">    </span><span class="c1">// grid-stride遍历，对本线程块私有的UB直方图做原子累加。</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">gridDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(;</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">byte_count</span><span class="p">;</span><span class="w"> </span><span class="n">index</span><span class="w"> </span><span class="o">+=</span><span class="w"> </span><span class="n">stride</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">asc_atomic_add</span><span class="p">(</span><span class="o">&amp;</span><span class="n">block_histogram</span><span class="p">[</span><span class="n">input</span><span class="p">[</span><span class="n">index</span><span class="p">]],</span><span class="w"> </span><span class="mi">1U</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="w">    </span><span class="n">asc_syncthreads</span><span class="p">();</span>

<span class="w">    </span><span class="c1">// 前256个线程各负责一个桶，将线程块局部结果原子累加到最终GM直方图。</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">bin_index</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span><span class="w"> </span><span class="n">bin_index</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">HISTOGRAM_BIN_COUNT</span><span class="p">;</span><span class="w"> </span><span class="n">bin_index</span><span class="w"> </span><span class="o">+=</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">asc_atomic_add</span><span class="p">(</span><span class="n">histogram</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">bin_index</span><span class="p">,</span><span class="w"> </span><span class="n">block_histogram</span><span class="p">[</span><span class="n">bin_index</span><span class="p">]);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>上述实现的功能与反例一致，线程块数量、线程数、输入读取方式和原子更新总次数均相同，唯一变化是原子操作的目标所在内存层级与竞争范围。该实现的性能数据如下：</p><table><thead><tr><th align="center">计数位置</th><th align="center">Task Duration（μs）</th></tr></thead><tbody><tr><td align="center">UB分块</td><td align="center">7.95</td></tr></tbody></table><p>两种实现的性能数据汇总如下：</p><table><thead><tr><th align="center">写法</th><th align="center">计数位置</th><th align="center">Task Duration（μs）</th></tr></thead><tbody><tr><td align="center"><strong>UB分块归约后汇总至GM</strong></td><td align="center"><strong>UB</strong></td><td align="center"><strong>7.95</strong></td></tr><tr><td align="center">GM全局直接累加</td><td align="center">GM</td><td align="center">424.22</td></tr></tbody></table><p>根据Task Duration数据，采用分层归约后执行耗时从424.22μs下降至7.95μs，降幅约98.1%，性能提升约53倍。收益来自两个叠加因素：</p><ul><li><strong>单次原子操作的处理开销降低</strong>：原子操作的目标由GM迁移至UB，访问路径缩短、延迟降低。在同一地址上的原子操作需排队执行的前提下，单次开销的差异随排队次数逐次累积。</li><li><strong>同一地址上排队的原子操作次数显著减少</strong>：反例中256个GM地址由全部线程共享，平均每个地址执行1024次原子操作；正例中每个线程块持有独立的256桶UB直方图，竞争范围限于本线程块的2048个线程，平均每个地址执行16次原子操作，且64个线程块之间的UB原子操作互不竞争、可并行执行。最终作用于GM的原子操作仅为<code>64 × 256 = 16384</code>次汇总，相比反例的262144次显著减少。</li></ul><p>两个因素共同作用，其收益显著高于UB初始化、<code>asc_syncthreads()</code>同步与GM汇总引入的额外开销。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>UB为线程块私有存储，总容量为256KB。分层归约适用于局部归约结果可完整放入UB的场景（如本样例的256个桶）。若归约目标规模过大、无法在UB中容纳，可采用部分归约或对目标进行分段处理。</p></div><h2 id="非必要不使用原子操作的返回值">非必要不使用原子操作的返回值<a class="header-anchor" href="#非必要不使用原子操作的返回值">​</a></h2><p>原子操作接口通常会返回目标地址上的旧值。是否使用返回值会影响编译器生成的指令：不使用返回值时，编译器可选择处理开销更低的原子指令；使用返回值时生成的指令开销更高。因此在业务逻辑不依赖旧值的场景下，应避免使用返回值。</p><p>【反例】纯计数场景仍接收并使用原子加的返回值。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// GM单地址，使用返回值。</span>
<span class="n">__global__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">atomic_add_gm_single_return</span><span class="p">(</span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">counter</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">volatile</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">old_value_sink</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_atomic_add</span><span class="p">(</span><span class="n">counter</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">);</span>
<span class="w">    </span><span class="p">(</span><span class="kt">void</span><span class="p">)</span><span class="n">old_value_sink</span><span class="p">;</span>
<span class="p">}</span>
</code></pre></div><p>【正例】不依赖旧值时直接丢弃返回值。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// GM单地址，不使用返回值。</span>
<span class="n">__global__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">atomic_add_gm_single_no_return</span><span class="p">(</span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">counter</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">asc_atomic_add</span><span class="p">(</span><span class="n">counter</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><p>在启动1个线程块、每个线程块2048个线程且全部线程竞争同一地址的配置下，分别在GM与UB上测试两种写法，性能数据如下：</p><table><thead><tr><th align="center">内存位置</th><th align="center">数据类型</th><th align="center">使用返回值（μs）</th><th align="center">不使用返回值（μs）</th><th align="center">耗时比值</th></tr></thead><tbody><tr><td align="center">GM</td><td align="center">int32_t</td><td align="center">421.59</td><td align="center">159.88</td><td align="center">2.64×</td></tr><tr><td align="center">UB</td><td align="center">int32_t</td><td align="center">3.17</td><td align="center">2.76</td><td align="center">1.15×</td></tr></tbody></table><p>根据Task Duration数据，GM上不使用返回值时耗时从421.59μs下降到159.88μs，降幅约62.1%；UB上从3.17μs下降到2.76μs，降幅约12.9%。指令形式带来的开销差异在GM上被显著放大，在UB上相对较小，因此在GM场景下更应避免使用返回值。</p><p>需要注意的是，该指令优化与数据类型相关，并非对所有类型都生效。在48个线程块、每个线程块256个线程、1024个紧密排布的GM目标地址的配置下，分别测试int32_t与int64_t，性能数据如下：</p><table><thead><tr><th align="center">数据类型</th><th align="center">使用返回值（μs）</th><th align="center">不使用返回值（μs）</th></tr></thead><tbody><tr><td align="center">int32_t</td><td align="center">110.95</td><td align="center">1.89</td></tr><tr><td align="center">int64_t</td><td align="center">54.28</td><td align="center">58.46</td></tr></tbody></table><p>int32_t不使用返回值时耗时降至1.89μs，而int64_t在两种写法下均为54~58μs量级、无明显差异，说明该指令优化仅对int32_t生效。因此避免使用返回值的收益主要体现在int32_t等可触发优化的类型上。</p><h2 id="分散GM上原子操作的目标地址">分散GM上原子操作的目标地址<a class="header-anchor" href="#分散GM上原子操作的目标地址">​</a></h2><p>本条优化方法以“原子操作必须在GM上执行”为前提。若原子目标可通过分层归约转移到UB，应优先采用上文的方法；仅当业务要求原子更新直接作用于GM时，才需要进一步关注目标地址在GM上的分布。</p><p>GM原子操作会经过L2 Cache层级，在L2侧完成“读—算—写”，并以128B Sector为处理粒度。原子操作的目标地址集中在同一个Sector内时处理效率较低，分布在更多Sector内时处理效率较高。因此在原子操作总次数不变的前提下，应尽量使目标地址覆盖更多Sector。</p><p>一个128B Sector可容纳32个int32_t地址（<code>32 × 4B = 128B</code>）。据此可构造两种地址布局：紧密排布使32个目标地址连续存放、集中在同一个Sector内；padding布局将相邻目标地址的间隔扩大到128B，使32个目标地址分别位于32个Sector中。</p><p><strong>图 3</strong> 紧密排布与padding地址布局对比示意图</p><p><img src="`+i+`" alt></p><p>下面以48个线程块、每个线程块256个线程、32个int32_t GM目标地址、每个地址上384个线程、每个线程执行1次原子加（共12288次原子加）的配置为例，通过函数入参<code>target_stride</code>控制地址布局，对比目标地址集中与分散两种情形。两种情形的目标地址数、每个地址上的线程数与原子加总次数完全一致，仅地址布局不同，因此可单独反映Sector分布的影响。</p><p>【反例】目标地址紧密排布，全部原子目标集中在同一个Sector内。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="nf">__launch_bounds__</span><span class="p">(</span><span class="n">MAX_THREADS_PER_BLOCK</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">atomic_add_gm_case4_i32_return</span><span class="p">(</span>
<span class="w">    </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">counters</span><span class="p">,</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">target_count</span><span class="p">,</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">threads_per_target</span><span class="p">,</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">target_stride</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">global_tid</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockDim</span><span class="p">.</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">threadIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span>
<span class="w">    </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">active_threads</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">target_count</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">threads_per_target</span><span class="p">;</span>
<span class="w">    </span><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">global_tid</span><span class="w"> </span><span class="o">&gt;=</span><span class="w"> </span><span class="n">active_threads</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="k">return</span><span class="p">;</span>
<span class="w">    </span><span class="p">}</span>

<span class="w">    </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">target_id</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">global_tid</span><span class="w"> </span><span class="o">%</span><span class="w"> </span><span class="n">target_count</span><span class="p">;</span>
<span class="w">    </span><span class="kt">int32_t</span><span class="o">*</span><span class="w"> </span><span class="n">target</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">counters</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">target_id</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">target_stride</span><span class="p">;</span>
<span class="w">    </span><span class="k">volatile</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">old_value_sink</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_atomic_add</span><span class="p">(</span><span class="n">target</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">);</span>
<span class="w">    </span><span class="p">(</span><span class="kt">void</span><span class="p">)</span><span class="n">old_value_sink</span><span class="p">;</span>
<span class="p">}</span>

<span class="c1">// target_stride取1：32个连续的int32_t地址占满一个128B Sector。</span>
<span class="n">atomic_add_gm_case4_i32_return</span><span class="o">&lt;&lt;&lt;</span><span class="mi">48</span><span class="p">,</span><span class="w"> </span><span class="mi">256</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span><span class="n">counters_device</span><span class="p">,</span><span class="w"> </span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="mi">384</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">);</span>
</code></pre></div><p>上述实现中，目标数组起始地址按128B对齐，<code>target_stride = 1</code>使32个目标地址连续存放，全部位于同一个Sector内。该实现的性能数据如下：</p><table><thead><tr><th align="center">地址布局</th><th align="center">target_stride</th><th align="center">覆盖Sector数</th><th align="center">Task Duration（μs）</th></tr></thead><tbody><tr><td align="center">紧密排布</td><td align="center">1</td><td align="center">1</td><td align="center">2164.72</td></tr></tbody></table><p>【正例】通过padding扩大目标地址间隔，使原子目标分散到更多Sector上。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 核函数（Kernel）不变，仅将target_stride从1增加到32：相邻目标地址间隔128B，32个地址分别位于32个Sector。</span>
<span class="n">atomic_add_gm_case4_i32_return</span><span class="o">&lt;&lt;&lt;</span><span class="mi">48</span><span class="p">,</span><span class="w"> </span><span class="mi">256</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span><span class="n">counters_device</span><span class="p">,</span><span class="w"> </span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="mi">384</span><span class="p">,</span><span class="w"> </span><span class="mi">32</span><span class="p">);</span>
</code></pre></div><p>上述实现的核函数（Kernel）与反例完全相同，数据类型、是否使用返回值、线程规模、目标地址数、每个地址上的线程数与原子加总次数均保持一致，仅将<code>target_stride</code>由1个int32_t元素增加到32个int32_t元素（即128B），使原子目标覆盖32个Sector。该实现的性能数据如下：</p><table><thead><tr><th align="center">地址布局</th><th align="center">target_stride</th><th align="center">覆盖Sector数</th><th align="center">Task Duration（μs）</th></tr></thead><tbody><tr><td align="center">padding</td><td align="center">32</td><td align="center">32</td><td align="center">80.17</td></tr></tbody></table><p>两种实现的性能数据汇总如下：</p><table><thead><tr><th align="center">写法</th><th align="center">地址布局</th><th align="center">覆盖Sector数</th><th align="center">Task Duration（μs）</th></tr></thead><tbody><tr><td align="center"><strong>padding分散目标地址</strong></td><td align="center"><strong>padding</strong></td><td align="center"><strong>32</strong></td><td align="center"><strong>80.17</strong></td></tr><tr><td align="center">目标地址紧密排布</td><td align="center">紧密排布</td><td align="center">1</td><td align="center">2164.72</td></tr></tbody></table><p>根据Task Duration数据，在工作负载完全相同的前提下，将目标地址由1个Sector分散到32个Sector后，执行耗时从2164.72μs下降到80.17μs，降幅约96.3%，性能提升约27倍。除增加地址间隔外，也可通过增加目标地址数或对结构体进行对齐处理实现相同效果。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>本节对照统一使用返回值。由上文可知，int32_t不使用返回值时会触发指令优化，其耗时主要由该优化决定，将掩盖Sector分布对性能的影响。</p></div><p>Sector覆盖数由目标地址的字节间隔决定，因此在目标地址数相同时，位宽更大的数据类型将占用更多Sector。评估数据类型对原子操作性能的影响时，需要区分位宽本身的开销与Sector覆盖变化带来的影响。</p><p>【总结】原子操作属于高开销指令，其耗时由同一地址上排队的原子操作次数与单条指令的处理开销共同决定。优化时可按以下顺序考虑：</p><ul><li><strong>优先采用分层归约，将原子操作从GM迁移至UB</strong>：能在UB完成的原子更新应避免直接在GM上执行。多线程块更新同一目标时，应先在各线程块的UB中完成局部归约，再由每个线程块向GM汇总，既降低单次原子操作的处理开销，又将竞争范围由全局拆分至线程块内部。</li><li><strong>非必要不使用返回值</strong>：不使用返回值时编译器可生成开销更低的原子指令，该差异在GM上尤为明显。</li><li><strong>原子操作必须在GM上执行时，分散其目标地址</strong>：GM原子操作以128B Sector为处理粒度，目标地址过于集中会降低处理效率，可通过padding、结构体对齐使原子目标覆盖更多Sector。</li></ul></article></div>`,1)])])}const m=a(e,[["render",o]]);export{u as __pageData,m as default};
